entries[231780] = { ["name"] = "Tome of Conjure Water VIII", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nRequires Level 60\nConjures 20 bottles of mountain spring water, providing the mage and his allies with something to drink.\n\nConjured items disappear if logged out for more than 15 minutes.\n\"Teaches you Conjure Water (Rank 8).\"" }
