entries[232312] = { ["name"] = "Blood of the Lightbringer", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nRequires Level 60\nUse: Apply the Blood of the Lightbringer to consecrate your weapon." }
entries[232324] = { ["name"] = "Bird Whistle", ["text"] = "Binds when picked up\nUse: Calls forth Pepe to ride on your head as you adventure together." }
entries[232344] = { ["name"] = "Vick's VIP Pass", ["text"] = "Unique\nUse: Attune yourself to Blackwing Lair! (30 Sec Cooldown)\n\"For close personal friends of Lord Victor Nefarius only!\"" }
entries[232357] = { ["name"] = "Draconic Avenger", ["text"] = "Binds when picked up\nTwo-Hand Axe\n201 - 303 Damage Speed 3.50\n(72.00 damage per second)\n+23 Strength\n+28 Agility\n+18 Stamina\nDurability 120 / 120\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 2%." }
