entries[232373] = { ["name"] = "Refined Eye of Sulfuras", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nUse: Attune with the fires within, allowing you to replace your Cat form with a more fiery visage." }
entries[232389] = { ["name"] = "Libram of Plenty", ["text"] = "Binds when picked up\nUnique\nRelic Libram\nRequires Level 60\nEquip: Your Crusader Strike spell restores an additional 10% of your maximum mana." }
entries[232390] = { ["name"] = "Idol of Celestial Focus", ["text"] = "Binds when picked up\nUnique\nRelic Idol\nRequires Level 60\nEquip: Increases the damage done by Starfall by 10%, but decreases its radius by 50%." }
entries[232391] = { ["name"] = "Idol of Feline Focus", ["text"] = "Binds when picked up\nUnique\nRelic Idol\nRequires Level 60\nEquip: Your Ferocious Bite ability no longer converts additional energy into damage, and refunds 30 energy on a Dodge, Miss, or Parry." }
entries[232392] = { ["name"] = "Totem of Relentless Thunder", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nRequires Level 60\nEquip: While a Shield is equipped, your melee attacks with Rockbiter Weapon trigger your Maelstrom Weapon rune 100 + (5 * Combo Points)% more often." }
entries[232409] = { ["name"] = "Totem of the Elements", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nRequires Level 60\nEquip: Your Elemental Focus talent now has a maximum of 2 charges, and is set to 2 charges when it triggers." }
entries[232414] = { ["name"] = "Dragontooth Blade", ["text"] = "Quest Item\nUnique\nClasses: Warrior\nRequires Level 60\nUse: Carve a scale from Nefarian's hide. Only usable when Nefarian has been significantly weakened in battle. (10 Sec Cooldown)" }
entries[232416] = { ["name"] = "Totem of Astral Flow", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nRequires Level 60\nEquip: Increases the attack power bonus on Windfury Weapon attacks by 68." }
entries[232419] = { ["name"] = "Totem of Conductive Currents", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nRequires Level 60\nEquip: While Frostbrand Weapon is active on your main hand weapon, your Water Shield triggers reduce the cast time of your next Chain Lightning spell within 15 sec by 20%, and increases its damage by 20%. Stacking up to 5 times." }
entries[232420] = { ["name"] = "Libram of Wrath", ["text"] = "Binds when picked up\nUnique\nRelic Libram\nRequires Level 60\nEquip: Causing damage with your Holy Shock spell reduces the cast time and mana cost of your next Holy Wrath cast within 15 sec by 20%, and increases its damage by 20%. Stacking up to 5 times." }
entries[232421] = { ["name"] = "Libram of Avenging", ["text"] = "Binds when picked up\nUnique\nRelic Libram\nRequires Level 60\nEquip: Your Avenger's Shield hits 2 fewer targets, but will hit its target 2 times." }
entries[232423] = { ["name"] = "Idol of Nurture", ["text"] = "Binds when picked up\nUnique\nRelic Idol\nRequires Level 60\nEquip: Increases healing done by Nourish by up to 77." }
