entries[232433] = { ["name"] = "Dense Runecloth Bandage", ["text"] = "Requires Level 50\nRequires First Aid (300)\nUse: Heals 3400 damage over 8 sec." }
entries[232434] = { ["name"] = "Manual: Dense Runecloth Bandage", ["text"] = "Requires First Aid (300)\nUse: Teaches you how to make a Dense Runecloth Bandage.\nDense Runecloth Bandage\nRequires Level 50\nRequires First Aid (300)\nUse: Heals 3400 damage over 8 sec.\nRequires Heavy Runecloth Bandage (2)" }
entries[232436] = { ["name"] = "Darkclaw Bisque", ["text"] = "Requires Level 45\nUse: Restores 2148 health over 30 sec. Must remain seated while eating. If you eat for 10 seconds will also increase your Spell Damage by 12 for 10 min." }
