entries[232454] = { ["name"] = "Emblem of the Wild Gods", ["text"] = "Binds to account\n\"Proof of assisting the Shadowtooth Emissary. Redeemable at the Rune Broker in capital cities.\"" }
entries[232455] = { ["name"] = "Emblem of Dishonor", ["text"] = "Binds to account\n\"Proof of confronting Illari Duskfeather. Redeemable at the Rune Broker in capital cities.\"" }
