entries[232457] = { ["name"] = "Emblem of the Worldcore", ["text"] = "Binds to account\n\"Proof of atunning to the Leyline Confluxes. Redeemable at the Rune Broker in capital cities.\"" }
entries[232458] = { ["name"] = "Rune of Improved Sanctuary", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your helm with the Improved Sanctuary rune:\n\nIncreases the damage prevented by your Blessing of Sanctuary by 100%, and increases damage done by your Blessing of Sanctuary by 20% of your shield block value.\n\"Teaches you a new Engraving ability.\"" }
entries[232459] = { ["name"] = "Rune of Backdraft", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your helm with the Backdraft rune:\n\nYour Conflagrate ability also grants 30% spellcasting haste for 15 sec and no longer consumes Immolate.\n\"Teaches you a new Engraving ability.\"" }
entries[232460] = { ["name"] = "Rune of Displacement", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your bracers with the Displacement rune:\n\nTeleports back to where you last cast Blink from and resets the cooldown on Blink. Only usable within 10 sec of casting Blink.\n\"Teaches you a new Engraving ability.\"" }
entries[232461] = { ["name"] = "Rune of Despair", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your bracers with the Despair rune:\n\nPeriodic damage from your spells can now be critical strikes and all your damaging spell critical strikes deal 200% damage.\n\"Teaches you a new Engraving ability.\"" }
entries[232462] = { ["name"] = "Rune of Purifying Power", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your bracers with the Purifying Power rune:\n\nReduces the cooldown on Exorcism and Holy Wrath by 50%, and Holy Wrath can now be cast at any target and will Stun Undead and Demon targets for 2 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[232549] = { ["name"] = "Logistics Task Briefing VI", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60" }
entries[232550] = { ["name"] = "Ashkandi, Greatsword of the Brotherhood", ["text"] = "Shadowflame\nBinds when picked up\nTwo-Hand Sword\n235 - 354 Damage Speed 3.60\n(81.81 damage per second)\n+20 Strength\n+23 Stamina\nDurability 120 / 120\nRequires Level 60\nEquip: +86 Attack Power.\n\"The initials A.L. are etched on the hilt.\"" }
entries[232551] = { ["name"] = "Draconic Maul", ["text"] = "Shadowflame\nBinds when picked up\nTwo-Hand Mace\n117 - 176 Damage Speed 2.00\n(73.25 damage per second)\n+33 Strength\n+21 Stamina\nDurability 120 / 120\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 2%.\nEquip: +260 Attack Power in Cat, Bear, and Dire Bear forms only." }
entries[232552] = { ["name"] = "Lok'amir il Romathis", ["text"] = "Shadowflame\nBinds when picked up\nUnique-Equipped\nMain Hand Mace\n47 - 127 Damage Speed 2.10\n(41.43 damage per second)\n+10 Stamina\n+18 Intellect\n+8 Spirit\nDurability 105 / 105\nRequires Level 60\nEquip: Increases damage and healing done by magical spells and effects by up to 86.\n\"The Hand of Nefarius\"" }
