entries[232606] = { ["name"] = "Ashjre'thul, Crossbow of Smiting", ["text"] = "Shadowflame\nBinds when picked up\nRanged Crossbow\n124 - 186 Damage Speed 3.40\n(45.59 damage per second)\n+7 Stamina\nDurability 90 / 90\nRequires Level 60\nEquip: +36 ranged Attack Power." }
entries[232607] = { ["name"] = "Heartstriker", ["text"] = "Shadowflame\nBinds when picked up\nRanged Bow\n98 - 183 Damage Speed 3.20\n(43.91 damage per second)\n+6 Stamina\nDurability 90 / 90\nRequires Level 60\nEquip: 2% chance on ranged hit to gain 1 extra attack. (Proc chance: 2%, 1s cooldown)\nEquip: +18 Attack Power." }
entries[232608] = { ["name"] = "Dragonbreath Hand Cannon", ["text"] = "Shadowflame\nBinds when picked up\nRanged Gun\n92 - 172 Damage Speed 3.00\n(44.00 damage per second)\n+14 Agility\n+7 Stamina\nDurability 90 / 90\nRequires Level 60\nUse: Charge up the Hand Cannon for 2.5 secs to inflict 500 Fire damage to enemies in a cone in front of you. Causes a high amount of threat. (30 Sec Cooldown)" }
entries[232610] = { ["name"] = "Formula: Magnificent Trollshine", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nRequiresZandalar Tribe\n- Honored\nUse: Teaches you how to create Magnificent Trollshine.\nMagnificent Trollshine\nRequires Level 45\nUse: While applied to target shield it increases spell damage and healing by up to 36 and increases Spell Critical chance by 1%. Lasts for 30 minutes.\n5 Charges\nRequires Flask of Mojo (3), Flask of Big Mojo (3), Large Brilliant Shard (2), Imbued Vial" }
entries[232611] = { ["name"] = "Magnificent Trollshine", ["text"] = "Requires Level 45\nUse: While applied to target shield it increases spell damage and healing by up to 36 and increases Spell Critical chance by 1%. Lasts for 30 minutes.\n5 Charges" }
entries[232652] = { ["name"] = "Zila Amanemodas", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Attune with the darkness within, allowing you better control over your inner demon." }
entries[233197] = { ["name"] = "Argent Training Manual", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Use the manual to call your Argent Squire for a training lesson in combat with the Silithid. Silithids killed in the squire's presence will increase your reputation with the Argent Dawn. (5 Min Cooldown)\n3 Charges" }
entries[233198] = { ["name"] = "Horn of the Dawn", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Rally your nearby party or raid members, granting them 10% increased spell critical strike chance, 5% increased melee and ranged critical strike chance, and 140 increased attack power. Lasts 2 hrs. Exclusive with similar world effects and unaffected by Chronoboons. (30 Sec Cooldown)" }
entries[233200] = { ["name"] = "Songflower Seed", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Summon a songflower that grants all your party or raid members 5% increased chance for a melee, ranged, or spell critical and 15 increased attributes for 1 hour. Exclusive with similar world effects. Unaffected by Chronoboons. (30 Sec Cooldown)" }
entries[233201] = { ["name"] = "Shimmering Globe", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Grants all your nearby party or raid members 200 increased attack power, 15% increased Stamina, and 3% increased spell critical strike chance for 2 hrs. Exclusive with similar world effects. Unaffected by Chronoboons. (30 Sec Cooldown)" }
entries[233206] = { ["name"] = "Overseer's Anvil", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Increases hitpoints by 300. 15% haste to melee attacks. 10 mana regen every 5 seconds. Lasts 1 hour. (30 Sec Cooldown)" }
entries[233208] = { ["name"] = "\"Defective\" Magic 8-Ball", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Grants all your party or raid members 10% increased damage done for 2 hrs. (30 Sec Cooldown)\n\"No matter how much you shake it, this toy always lands on the same dark fortune: Painful Death.\"" }
entries[233209] = { ["name"] = "Firewater Cauldron", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Summon a cauldron of Firewater for 10 min, useable by all members of your party or raid to increase melee attack power by 35 and size for 1 hour. (30 Sec Cooldown)" }
entries[233211] = { ["name"] = "Spirit Conch", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Grants all your party or raid members 10% increased movement speed and 15% increased stats for 2 hrs. (30 Sec Cooldown)" }
entries[233213] = { ["name"] = "Ancient Lodestone", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Weakens Elemental members of the Abyssal Council in Silithus, reducing all damage they deal by 20%. Lasts 2 min. (1 Min Cooldown)\n10 Charges" }
entries[233215] = { ["name"] = "Explosive Sand Trap", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Place a trap at a nearby location that explodes when a Silithid from Hive'Ashi, Hive'Regal, or Hive'Zora approaches, causing the Silithid to take 6% of its health in damage every 3 sec for 15 sec. (1 Min Cooldown)\n10 Charges" }
entries[233216] = { ["name"] = "Freez-O-Matic Ray", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Freezes a Silithid within the Hive'Ashi, Hive'Regal, or Hive'Zora hives for 1 min. Effect broken by any damage. (1 Min Cooldown)\n10 Charges" }
entries[233217] = { ["name"] = "Tunneler's Incense", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Inhaling this incense causes you to fade into the shadows, allowing you to sneak around while inside Hive'Ashi, Hive'Regal, or Hive'Zora, but reduces your speed by 50%. Lasts 1 min. (1 Min Cooldown)\n10 Charges" }
entries[233226] = { ["name"] = "Ancient Zandalarian Rope", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Throw the ancient rope to restrain a silithid of Hive'Ashi, Hive'Regal, or Hive'Zora and pull them toward you. May not be used on enemies higher than level ( 60 + 1) or which are marked as boss enemies. (1 Min Cooldown)\n10 Charges\n\"Used in lost ages by trolls of the Empire of Zul to battle the Aqir.\"" }
entries[233250] = { ["name"] = "Ancient Branch", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Use the branch to call an Ancient of War to assist you in fighting Silithids. (15 Min Cooldown)\n3 Charges" }
entries[233351] = { ["name"] = "Light Green Qiraji Resonating Crystal", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 60\nUse: Summons and dismisses a rideable Qiraji battle tank. This is a very fast mount. (3 Sec Cooldown)" }
entries[233352] = { ["name"] = "Dark Blue Qiraji Resonating Crystal", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 60\nUse: Summons and dismisses a rideable Qiraji battle tank. This is a very fast mount. (3 Sec Cooldown)" }
