entries[233356] = { ["name"] = "Orange Qiraji Resonating Crystal", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 60\nUse: Summons and dismisses a rideable Qiraji battle tank. This is a very fast mount. (3 Sec Cooldown)" }
entries[233357] = { ["name"] = "Twilight Qiraji Resonating Crystal", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 60\nUse: Summons and dismisses a rideable Qiraji battle tank. This is a very fast mount. (3 Sec Cooldown)" }
entries[233358] = { ["name"] = "Tamed Silithid Tank", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 60\nUse: Emits a high frequency sound, forcing a silithid tank to burrow out from its home beneath the Temple of Ahn'Qiraj. The silithid is obedient to the summoner and can be used as a mount within the Temple of Ahn'Qiraj. Any hostile action towards the rider forces the tank underground. (3 Sec Cooldown)" }
