entries[233376] = { ["name"] = "Conqueror's Spaulders", ["text"] = "Binds when picked up\nShoulder Plate\n659 Armor\n+18 Strength\n+13 Agility\n+20 Stamina\nDurability 100 / 100\nClasses: Warrior\nRequires Level 60\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Increased Defense +9.\n\nConqueror's Bulwark (0/5)\nConqueror's Crown\nConqueror's Spaulders\nConqueror's Breastplate\nConqueror's Legguards\nConqueror's Greaves\n(2) Set : Reduces the cooldown on Thunder Clap by 100%.\n(4) Set : Your Shield Slam deals 100% increased threat and its cooldown is reset if it is Dodged, Parried, or Blocked." }
entries[233377] = { ["name"] = "Doomcaller's Footwraps", ["text"] = "Binds when picked up\nFeet Cloth\n82 Armor\n+8 Stamina\n+10 Intellect\n+14 Spirit\nDurability 50 / 50\nClasses: Warlock\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 28.\n\nDoomcaller's Corruption (0/5)\nDoomcaller's Circlet\nDoomcaller's Mantle\nDoomcaller's Trousers\nDoomcaller's Footwraps\nDoomcaller's Robes\n(2) Set : Reduces the cooldown on your Chaos Bolt by 50% and increases Chaos Bolt and Shadow Bolt damage done by 10%. In addition, Chaos Bolt can now trigger your Improved Shadow Bolt talent and causes it to have 26 additional charges (does not stack with Shadowflame's additional charges).\n(4) Set : Each time you hit a target with Conflagrate, you gain 5% increased Fire damage for 20 sec, stacking up to 2 times." }
entries[233378] = { ["name"] = "Doomcaller's Trousers", ["text"] = "Binds when picked up\nLegs Cloth\n107 Armor\n+15 Stamina\n+17 Intellect\n+20 Spirit\nDurability 75 / 75\nClasses: Warlock\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 35.\n\nDoomcaller's Corruption (0/5)\nDoomcaller's Circlet\nDoomcaller's Mantle\nDoomcaller's Trousers\nDoomcaller's Footwraps\nDoomcaller's Robes\n(2) Set : Reduces the cooldown on your Chaos Bolt by 50% and increases Chaos Bolt and Shadow Bolt damage done by 10%. In addition, Chaos Bolt can now trigger your Improved Shadow Bolt talent and causes it to have 26 additional charges (does not stack with Shadowflame's additional charges).\n(4) Set : Each time you hit a target with Conflagrate, you gain 5% increased Fire damage for 20 sec, stacking up to 2 times." }
